using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// The in-song HUD sign: a backlit overhead subway guide sign, as a prefab
/// (Resources/UI/MetroSign, generated by Metro > Build HUD Sign Prefab and tuned in the
/// Inspector from there), laid out after the hand-drawn sketch: the thumbnail (cover
/// art, or the song's station badge on a white tile), title and artist, the level as a
/// lit line badge | the score with the song's progress lit under it | a user badge
/// in a lit line-colour ring, the player's name and options, and the lit yellow arrow panel. The
/// sections are split by thick lit white rules. Layer groups from the bottom: 1 the
/// black metal housing, 2 the dark face, 3 the rules, 4 song, 5 score, 6 player, 7 the
/// arrow panel, 8 the glass in front.
///
/// Every lit layer carries a <see cref="SignEmission"/> for its own HDR brightness; the
/// lettering's glow is in the TextMeshPro materials (Assets/UI/MetroSign/Materials).
/// RhythmJudgementUI puts it on its camera-space canvas and feeds it.
/// </summary>
public sealed class MetroSignHud : MonoBehaviour
{
    public const string ResourcePath = "UI/MetroSign";

    [Header("Song")]
    [Tooltip("The station badge on its tile, shown when the chart has no cover art.")]
    [SerializeField] private GameObject badge;
    [SerializeField] private Graphic badgeRing;
    [SerializeField] private TMP_Text badgeLetter;
    [SerializeField] private TMP_Text badgeNumber;
    [SerializeField] private RawImage cover;
    [SerializeField] private TMP_Text titleText;
    [SerializeField] private TMP_Text artistText;
    [SerializeField] private Graphic levelRing;
    [SerializeField] private Graphic levelBleed;
    [SerializeField] private TMP_Text levelNumber;
    [Tooltip("Opacity of the line-colour light around the level badge.")]
    [SerializeField, Range(0f, 1f)] private float levelBleedAlpha = 0.35f;

    [Header("Score")]
    [SerializeField] private TMP_Text scoreText;
    [SerializeField] private RectTransform progressFill;
    [SerializeField] private Graphic progressFillGraphic;
    [Tooltip("Size of the % sign relative to the digits.")]
    [SerializeField, Range(0.2f, 1f)] private float percentSignScale = 0.5f;

    [Header("Player")]
    [SerializeField] private Graphic userRing;
    [SerializeField] private Graphic userBleed;
    [SerializeField] private TMP_Text playerName;
    [SerializeField] private TMP_Text playerStatus;

    /// <summary>Shows a song: its station badge (or cover art) in <paramref name="lineColor"/>, title, artist and level.</summary>
    public void SetSong(string title, string artist, Color lineColor, string letter, string number, int level, Texture2D jacket)
    {
        titleText.text = title ?? string.Empty;
        artistText.text = artist ?? string.Empty;
        badgeLetter.text = letter ?? string.Empty;
        badgeNumber.text = number ?? string.Empty;
        badgeRing.color = Opaque(lineColor);
        levelRing.color = Opaque(lineColor);
        levelBleed.color = WithAlpha(lineColor, levelBleedAlpha);
        userRing.color = Opaque(lineColor);
        userBleed.color = WithAlpha(lineColor, levelBleedAlpha);
        levelNumber.text = SongGenre.FormatStation(level);
        progressFillGraphic.color = Opaque(lineColor);
        SetProgress(0f);

        bool hasCover = jacket != null;
        badge.SetActive(!hasCover);
        cover.gameObject.SetActive(hasCover);
        if (hasCover)
        {
            cover.texture = jacket;
            float aspect = (float)jacket.width / Mathf.Max(1, jacket.height);
            cover.uvRect = aspect >= 1f
                ? new Rect((1f - 1f / aspect) * 0.5f, 0f, 1f / aspect, 1f)
                : new Rect(0f, (1f - aspect) * 0.5f, 1f, aspect);
        }
    }

    /// <summary>The achievement rate as the sign shows it: four decimals and a smaller %, e.g. 99.9999%.</summary>
    public void SetScore(float percent)
    {
        int signSize = Mathf.RoundToInt(percentSignScale * 100f);
        scoreText.text = $"{percent:0.0000}<size={signSize}%>%</size>";
    }

    /// <summary>The song's progress (0..1) along the rule under the score.</summary>
    public void SetProgress(float progress)
    {
        progressFill.anchorMax = new Vector2(Mathf.Clamp01(progress), 1f);
    }

    /// <summary>The player's name and the options in effect (rich text).</summary>
    public void SetPlayer(string name, string status)
    {
        playerName.text = (name ?? string.Empty).Trim();
        playerStatus.text = status ?? string.Empty;
    }

    private static Color Opaque(Color color)
    {
        color.a = 1f;
        return color;
    }

    private static Color WithAlpha(Color color, float alpha)
    {
        color.a = alpha;
        return color;
    }
}
